// spec: specs/authz-isolation.md (1.1) · кейс AZ-01 · две роли (parent-b, parent) — пишет autotest-writer
// parent-b пытается начать детскую сессию для ребёнка семьи A → 403 как у несуществующего;
// parent (оператор) видит в authz_audit строку authz_denied без данных ребёнка; parent-b журнал не читает.
// Паролей и PIN нет. parent-b.json в режим ребёнка НЕ переводится (решение 08.11, #8ca267: режим ребёнка на сервере
// «запирает» файл входа): свой p_device_id берём из запроса передачи, который ПЕРЕХВАТЫВАЕТСЯ и обрывается (route.abort) —
// до сервера он не доходит, детская сессия не открывается. Отказы 403 (чужой / несуществующий ребёнок) сессию не открывают.
// Записи в журнал — побочный след, не данные семьи.
import { test, expect } from '../../fixtures';
import { captureSupabase, jwtPayload } from '../session-auth/session-auth.helpers';
import { api, LEAK_MARKERS, QA_B1, QA_R2_1, randomMissingId } from './authz.helpers';

test.use({ viewport: { width: 1280, height: 800 } });

test('Чужой ребёнок в start_child_session → 403 как у несуществующего; оператор видит authz_denied без данных ребёнка @desktop #25b101', async ({ asUser }) => {
  const parentB = await asUser('parent-b');
  const parentA = await asUser('parent');

  // 1) parent-b: заголовки и свой p_device_id из запроса приложения при передаче своего ребёнка
  const sbB = await captureSupabase(parentB, '/children');
  const uidB = jwtPayload(sbB.authorization).sub as string;
  // TODO verify: имя RPC и поле p_device_id в теле запроса передачи (research/25b101/r5-p1a-parentb.json: «p_device_id:<own device>»)
  // Запрос передачи своего ребёнка перехватываем и обрываем: на сервер он не уходит → parent-b.json не в режиме ребёнка.
  let startBody: Record<string, unknown> | undefined;
  await parentB.route('**/rest/v1/rpc/start_child_session*', async (route) => {
    if (route.request().method() === 'POST') startBody = route.request().postDataJSON() ?? {};
    await route.abort();
  });
  await parentB.goto(`/children/${QA_B1}/handover`);
  await parentB.getByRole('button', { name: 'QA-B1, בואו נתחיל!' }).filter({ visible: true }).first().click();
  await expect.poll(() => startBody, { message: 'приложение отправило start_child_session (перехвачен, не дошёл до сервера)' }).toBeTruthy();
  await parentB.unroute('**/rest/v1/rpc/start_child_session*');
  const deviceId = String(startBody?.p_device_id ?? '');
  expect(deviceId, 'p_device_id из запроса приложения').toBeTruthy();

  // 2) Токеном parent-b: чужой ребёнок и несуществующий id
  const foreign = await api(parentB.request, sbB, 'POST', '/rest/v1/rpc/start_child_session', { p_child_id: QA_R2_1, p_device_id: deviceId });
  const missing = await api(parentB.request, sbB, 'POST', '/rest/v1/rpc/start_child_session', { p_child_id: randomMissingId(), p_device_id: deviceId });
  expect(foreign.status, `чужой: ${foreign.text}`).toBe(403);
  expect(missing.status, `несуществующий: ${missing.text}`).toBe(foreign.status);
  expect(foreign.text, 'тело для чужого = телу для несуществующего (AC2)').toBe(missing.text);
  for (const m of LEAK_MARKERS('QA-R2-1')) expect(foreign.text, `в отказе нет ${m}`).not.toContain(m);

  // Время сервера отказа минус 5 с — нижняя граница поиска в журнале
  const since = new Date(new Date(foreign.date ?? Date.now()).getTime() - 5_000).toISOString();

  // 3) parent-b журнал не читает
  const ownAudit = await api(parentB.request, sbB, 'GET', `/rest/v1/authz_audit?select=*&target_id=eq.${QA_R2_1}`);
  if (ownAudit.status === 200) expect(JSON.parse(ownAudit.text), 'parent-b не видит строк журнала').toEqual([]);
  else expect([401, 403, 404], `authz_audit для parent-b: ${ownAudit.text}`).toContain(ownAudit.status);

  // 4) parent (оператор) видит строку authz_denied
  const sbA = await captureSupabase(parentA, '/children');
  const q =
    `/rest/v1/authz_audit?select=*&action=eq.authz_denied&operation=eq.start_child_session` +
    `&target_id=eq.${QA_R2_1}&user_id=eq.${uidB}&created_at=gte.${encodeURIComponent(since)}&order=created_at.desc`;
  let rows: Record<string, unknown>[] = [];
  await expect
    .poll(
      async () => {
        const r = await api(parentA.request, sbA, 'GET', q);
        expect(r.status, `authz_audit оператором: ${r.text}`).toBe(200);
        rows = JSON.parse(r.text);
        return rows.length;
      },
      { message: 'строка authz_denied появилась в журнале', timeout: 15_000 },
    )
    .toBeGreaterThan(0);

  const row = rows[0];
  expect(row.allowed, 'allowed=false').toBe(false);
  expect(row.target_type, 'target_type=child').toBe('child');
  const rowText = JSON.stringify(row);
  for (const m of LEAK_MARKERS('QA-R2-1')) expect(rowText, `в строке журнала нет ${m}`).not.toContain(m);
});
